package game.world;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.*;
import org.springframework.test.annotation.DirtiesContext;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT)
@DirtiesContext(classMode=DirtiesContext.ClassMode.AFTER_CLASS)
@EnabledIfEnvironmentVariable(named="PHASE1_DATABASE_URL",matches="jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/qingyu_phase1_[a-z0-9_]+")
class HandoverLawIntegrationTest {
 @Test void battleHandoverCostsSenderOneApAndReceiverNeedsNoTurn(){synchronized(world){UUID a=actor(),b=actor();neighbors(a,b);equipment.give(a,"bread",2);UUID battle=world.startBattle(a,b,world.map().version());db.update("update battle_encounters set turn_account_id=?,turn_points=4 where id=?",a,battle);UUID id=offer(a,b,"gift",2);tx().executeWithoutResult(s->{handovers.accept(b,new HandoverService.Accept(id,List.of(new HandoverService.Line("bread",1))),0);battles.payHandover(a,Set.of(a,b),0);});assertEquals(3,db.queryForObject("select turn_points from battle_encounters where id=?",Integer.class,battle));assertTrue(db.queryForObject("select handed_over from battle_actors where encounter_id=? and account_id=?",Boolean.class,battle,a));}}
 @Test void turnEndCancelsPendingAndSprintRejectsOffer(){synchronized(world){UUID a=actor(),b=actor();neighbors(a,b);equipment.give(a,"bread",2);UUID battle=world.startBattle(a,b,world.map().version());db.update("update battle_encounters set turn_account_id=?,turn_points=4 where id=?",a,battle);db.update("update battle_actors set sprinted=true where encounter_id=? and account_id=?",battle,a);assertThrows(RuntimeException.class,()->offer(a,b,"gift",2));db.update("update battle_actors set sprinted=false where encounter_id=? and account_id=?",battle,a);offer(a,b,"gift",2);tx().executeWithoutResult(s->battles.endTurn(a,Set.of(a,b),System.currentTimeMillis()));assertEquals(2,equipment.available(a,"bread"));}}
 @Test void npcAcceptsOnlyShortageThroughSharedSettlement(){synchronized(world){UUID a=actor();var s=law.stations(a).getFirst();UUID b=(UUID)s.get("officer_id");runtime.put(a,(UUID)s.get("scene_id"),new WorldMap.Hex(((Number)s.get("board_q")).intValue(),((Number)s.get("board_r")).intValue()));equipment.give(a,"bread",5);db.update("insert into npc_supply_targets values(?,'bread',2)",b);UUID id=offer(a,b,"sell",5);tx().executeWithoutResult(t->{var acceptance=handovers.npcAcceptance(id);assertEquals(2,acceptance.lines().getFirst().quantity());handovers.accept(b,acceptance,0);});assertEquals(3,equipment.available(a,"bread"));assertEquals(6,equipment.available(a,"copper_coin"));assertEquals(2,equipment.available(b,"bread"));}}
 @Test void corpseTransferPreservesIdentityAndPausedLifetime(){synchronized(world){UUID a=actor(),b=actor(),victim=actor();neighbors(a,b);long now=System.currentTimeMillis();tx().executeWithoutResult(s->characters.die(victim,now));UUID corpse=db.queryForObject("select id from loot_containers where source_id=? order by created_at desc limit 1",UUID.class,victim);db.update("update loot_containers set carrier_id=?,expires_at=null,remaining_ms=123456 where id=?",a,corpse);UUID id=tx().execute(s->handovers.propose(a,new HandoverService.Offer(b,"gift",List.of(),UUID.randomUUID(),List.of(corpse)),now));assertThrows(RuntimeException.class,()->tx().executeWithoutResult(s->db.update("delete from loot_containers where id=?",corpse)));tx().execute(s->handovers.accept(b,new HandoverService.Accept(id,List.of(),List.of(corpse)),now));assertEquals(b,db.queryForObject("select carrier_id from loot_containers where id=?",UUID.class,corpse));assertEquals(123456,db.queryForObject("select remaining_ms from loot_containers where id=?",Long.class,corpse));}}
 @Test void bountyDoesNotClearOtherFactionAndOfficerDeathStopsService(){synchronized(world){UUID a=actor(),b=actor();long now=System.currentTimeMillis();db.update("insert into factions values('test-other','测试其他势力') on conflict do nothing");db.update("insert into crimes(actor,faction_id,reason,created_at) values(?,'test-other','旧罪',?)",a,now);tx().executeWithoutResult(s->{law.hostile(a,b,"攻击",now);characters.die(a,now);});UUID corpse=db.queryForObject("select id from loot_containers where source_id=? order by created_at desc limit 1",UUID.class,a);var station=law.stations(b).getFirst();runtime.put(b,(UUID)station.get("scene_id"),new WorldMap.Hex(((Number)station.get("board_q")).intValue(),((Number)station.get("board_r")).intValue()));db.update("update loot_containers set carrier_id=?,expires_at=null where id=?",b,corpse);var claim=new LawService.Claim((UUID)station.get("id"),corpse,UUID.randomUUID());tx().executeWithoutResult(s->characters.die((UUID)station.get("officer_id"),now));assertThrows(RuntimeException.class,()->tx().execute(s->law.claim(b,claim,now)));assertNotNull(law.board(b,(UUID)station.get("id"),now));db.update("update characters set life='alive' where id=?",station.get("officer_id"));tx().execute(s->law.claim(b,claim,now));assertTrue(law.wanted(a,"test-other"));assertFalse(law.wanted(a,"qingyu"));}}
 @DynamicPropertySource static void config(DynamicPropertyRegistry r){r.add("spring.datasource.url",()->System.getenv("PHASE1_DATABASE_URL"));r.add("spring.datasource.username",()->"worldgame");r.add("spring.datasource.password",()->"local-only");r.add("app.admin-password",()->"phase-one-local-test-only");}
 @Autowired WorldService world;@Autowired AccountService accounts;@Autowired CharacterService characters;@Autowired SceneRuntime runtime;@Autowired SceneService scenes;@Autowired HandoverService handovers;@Autowired LawService law;@Autowired EquipmentService equipment;@Autowired BattleService battles;@Autowired JdbcTemplate db;@Autowired PlatformTransactionManager manager;
 TransactionTemplate tx(){return new TransactionTemplate(manager);}
 @BeforeEach void reset(){synchronized(world){db.update("delete from handovers");db.update("delete from crimes");db.update("delete from production_tasks");battles.reset();db.update("delete from scene_portals");db.update("delete from scene_documents");scenes.refresh();db.update("update characters set next_move=? where kind<>'player'",Long.MAX_VALUE);}}
 UUID actor(){var a=accounts.register("law"+UUID.randomUUID().toString().substring(0,12),"local-test-password",world.map().spawn());db.update("update accounts set approved=true,entered=true where id=?",a.id());characters.ensurePlayers();var h=world.map().tiles().stream().filter(t->t.place()!=null&&t.place().type().equals("town")).findFirst().orElseThrow().hex();characters.relocate(a.id(),h.q(),h.r());world.enterScene(a.id(),world.map().version());return a.id();}
 void neighbors(UUID a,UUID b){var p=runtime.position(a);var map=runtime.map(p.sceneId());var taken=runtime.occupied(map.id(),a);taken.remove(runtime.position(b).hex());for(var c:map.cells())if(c.walkable()&&!taken.contains(c.hex()))for(var n:c.hex().neighbors())if(!taken.contains(n)&&map.cells().stream().anyMatch(x->x.hex().equals(n)&&x.walkable())){runtime.put(a,map.id(),c.hex());runtime.put(b,map.id(),n);return;}throw new AssertionError();}
 UUID offer(UUID a,UUID b,String mode,int n){return tx().execute(s->handovers.propose(a,new HandoverService.Offer(b,mode,List.of(new HandoverService.Line("bread",n)),UUID.randomUUID()),System.currentTimeMillis()));}
 @Test void partialGiftReservesAndReplayDoesNotDuplicate(){synchronized(world){UUID a=actor(),b=actor();neighbors(a,b);equipment.give(a,"bread",5);UUID id=offer(a,b,"gift",5);assertEquals(0,equipment.available(a,"bread"));assertThrows(RuntimeException.class,()->equipment.consume(a,"bread",1));var accept=new HandoverService.Accept(id,List.of(new HandoverService.Line("bread",2)));tx().execute(s->handovers.accept(b,accept,System.currentTimeMillis()));tx().execute(s->handovers.accept(b,accept,System.currentTimeMillis()));assertEquals(3,equipment.available(a,"bread"));assertEquals(2,equipment.available(b,"bread"));}}
 @Test void salePaysActualQuantityAndNeverSpendsReservedMoney(){synchronized(world){UUID a=actor(),b=actor(),c=actor();neighbors(a,b);equipment.give(a,"bread",5);equipment.give(b,"copper_coin",9);UUID id=offer(a,b,"sell",5);assertThrows(RuntimeException.class,()->tx().execute(s->handovers.accept(b,new HandoverService.Accept(id,List.of(new HandoverService.Line("bread",5))),0)));tx().execute(s->handovers.accept(b,new HandoverService.Accept(id,List.of(new HandoverService.Line("bread",3))),0));assertEquals(9,equipment.available(a,"copper_coin"));assertEquals(0,equipment.available(b,"copper_coin"));assertEquals(2,equipment.available(a,"bread"));}}
 @Test void moveAwayCancelsAndReleases(){synchronized(world){UUID a=actor(),b=actor();neighbors(a,b);equipment.give(a,"bread",3);UUID id=offer(a,b,"gift",3);runtime.leave(b);tx().execute(s->handovers.prune(Set.of(a,b)));assertEquals(3,equipment.available(a,"bread"));assertThrows(RuntimeException.class,()->tx().execute(s->handovers.accept(b,new HandoverService.Accept(id,List.of(new HandoverService.Line("bread",1))),0)));}}
 @Test void playerDeathKeepsInventoryAndSnapshotsOnlyOldCrimes(){synchronized(world){UUID a=actor(),b=actor();neighbors(a,b);equipment.give(a,"bread",3);long now=System.currentTimeMillis();tx().executeWithoutResult(s->law.hostile(a,b,"攻击",now));assertTrue(law.wanted(a,"qingyu"));tx().executeWithoutResult(s->characters.die(a,now));assertEquals(3,equipment.available(a,"bread"));UUID corpse=db.queryForObject("select id from loot_containers where source_id=? order by created_at desc limit 1",UUID.class,a);assertEquals(1,db.queryForObject("select cardinality(crime_ids) from corpse_bounties where corpse_id=?",Integer.class,corpse));db.update("insert into crimes(actor,faction_id,reason,created_at) values(?,'qingyu','新犯罪',?)",a,now+1);
  var station=law.stations(b).getFirst();runtime.put(b,(UUID)station.get("scene_id"),new WorldMap.Hex(((Number)station.get("board_q")).intValue(),((Number)station.get("board_r")).intValue()));db.update("update loot_containers set carrier_id=?,expires_at=null where id=?",b,corpse);var request=new LawService.Claim((UUID)station.get("id"),corpse,UUID.randomUUID());tx().execute(s->law.claim(b,request,now+2));tx().execute(s->law.claim(b,request,now+3));assertEquals(1,equipment.available(b,"silver_coin"));assertEquals(1,db.queryForObject("select count(*) from crimes where actor=? and cleared_at is null",Integer.class,a));}}
 @Test void leavingFactionTimesOutButDeathDoesNotClear(){synchronized(world){UUID a=actor(),b=actor();long now=System.currentTimeMillis();tx().executeWithoutResult(s->law.hostile(a,b,"攻击",now));var h=characters.get(a).hex();db.update("delete from jurisdiction where world_version=? and q=? and r=?",world.map().version(),h.q(),h.r());tx().execute(s->law.advance(now));assertTrue(law.wanted(a,"qingyu"));tx().execute(s->law.advance(now+1799999));assertTrue(law.wanted(a,"qingyu"));tx().execute(s->law.advance(now+1800000));assertFalse(law.wanted(a,"qingyu"));db.update("insert into jurisdiction values(?,?,?,'qingyu',true)",world.map().version(),h.q(),h.r());}}
 @Test void changedPriceMustRequireNewOffer(){synchronized(world){UUID a=actor(),b=actor();neighbors(a,b);equipment.give(a,"bread",1);equipment.give(b,"copper_coin",9);UUID id=offer(a,b,"sell",1);try{db.update("update item_definitions set buy_price=4 where code='bread'");assertThrows(RuntimeException.class,()->tx().execute(s->handovers.accept(b,new HandoverService.Accept(id,List.of(new HandoverService.Line("bread",1))),0)));}finally{db.update("update item_definitions set buy_price=3 where code='bread'");}}}
}
